INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Singleton-Pattern nur für globale Variablen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Ressourcensteuerung generell"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Singleton-Pattern?', 3, '[{"text": "Globale Ressourcensteuerung", "correct": true, "because": "Sichert einzige Instanz"}, {"text": "Datenfluss optimieren", "correct": false, "because": "Kein Datenfokus"}, {"text": "UI-Gestaltung", "correct": false, "because": "Kein Designaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Singleton-Pattern?', 5, '[{"text": "Statische Instanz", "correct": true, "because": "Speichert einzige Instanz"}, {"text": "Privater Konstruktor", "correct": true, "because": "Verhindert Mehrfachinstanzierung"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Singleton sorgt für eine einzige Instanz. b) Es ist immer thread-sicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Threadsicherheit extra implementieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Singleton-Pattern?', 4, '[{"text": "Instanzkontrolle", "correct": false, "because": "Kern des Patterns"}, {"text": "Privater Zugriff", "correct": false, "because": "Schützt Instanz"}, {"text": "UI-Design", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Singleton-Pattern auch ohne statische Methode funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Statische Methode typisch"}, {"text": "Ja", "correct": false, "because": "Selten ohne statischen Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der private Konstruktor im Singleton-Pattern?', 3, '[{"text": "Verhindert Instanzierung", "correct": true, "because": "Nur Singleton kontrolliert"}, {"text": "Daten speichern", "correct": false, "because": "Kein Speicherfokus"}, {"text": "UI steuern", "correct": false, "because": "Nicht UI-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum Singleton-Pattern?', 5, '[{"text": "GetInstance-Methode", "correct": true, "because": "Zugriff auf Instanz"}, {"text": "Statische Variable", "correct": true, "because": "Hält einzige Instanz"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Singleton steuert globale Zugriffe. b) Es ist immer die beste Lösung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer optimal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Singleton-Pattern?', 4, '[{"text": "Privater Konstruktor", "correct": false, "because": "Schützt Instanz"}, {"text": "Statische Methode", "correct": false, "because": "Zugriff ermöglichen"}, {"text": "Netzwerkprotokolle", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Singleton-Pattern nur für globale Variablen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Ressourcen wie Logger"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Singleton-Pattern?', 4, '[{"text": "Einmalige Instanz", "correct": true, "because": "Ressourcen sparen"}, {"text": "Kontrollierter Zugriff", "correct": true, "because": "Global geregelt"}, {"text": "Datenfluss", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Singleton-Pattern immer thread-sicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Extra Synchronisation nötig"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Singleton-Pattern?', 3, '[{"text": "Instanzkontrolle", "correct": true, "because": "Sichert Einzigartigkeit"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Kontrolle zählt mehr"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Singleton nutzt statische Methoden. b) Es ist für mehrere Instanzen gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur eine Instanz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien profitieren vom Singleton-Pattern?', 5, '[{"text": "Logging", "correct": true, "because": "Einheitliche Protokollierung"}, {"text": "Konfigurationsmanagement", "correct": true, "because": "Zentraler Zugriff"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Animation", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Singleton-Pattern unwichtig?', 3, '[{"text": "Instanzsicherung", "correct": false, "because": "Kern des Patterns"}, {"text": "Privater Konstruktor", "correct": false, "because": "Verhindert Instanzen"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das Singleton-Pattern mehrere Instanzen erlauben?', 3, '[{"text": "Nein", "correct": true, "because": "Eine Instanz ist Ziel"}, {"text": "Ja", "correct": false, "because": "Widerspricht Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Singleton-Pattern für Tests problematisch ist?', 2, '[{"text": "Ja", "correct": true, "because": "Globale Instanz schwer mockbar"}, {"text": "Nein", "correct": false, "because": "Testprobleme bekannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Singleton-Instanz?', 4, '[{"text": "Statische Variable", "correct": true, "because": "Hält einzige Instanz"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "UI-Komponente", "correct": false, "because": "Nicht UI-spezifisch"}]');
